// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max);
        // adversarial counterparty that refuses any funds
        Reverter receiver = new Reverter();
        vm.deal(address(c), amount);
        // owner is the test contract (deployer of c)
        bool ok;
        try c.sendTo(address(receiver), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: sending to a receiver that refuses funds must revert.
        assertTrue(!ok, "sendTo must revert when the receiver refuses funds");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
